ui.css:
.bar { position: relative; width: 250px; height: 26px; background: linear-gradient(180deg, #fffaf1 0 50%, #e9ddc7 50% 100%); box-shadow: 0 0 0 1px rgba(120,96,80,.26), 3px 4px 0 rgba(82,60,72,.16); overflow: hidden; }
.bar-fill { height: 100%; background: linear-gradient(180deg, rgba(255,255,255,.2) 0 50%, rgba(90,24,14,.13) 50% 100%), repeating-linear-gradient(62deg, #ee8063 0 15px, #df6c52 15px 30px); box-shadow: 1px 0 0 #9b4136; }
.envelope { position: relative; isolation: isolate; padding: 9px 30px 7px; background: #fbf5e8; box-shadow: 0 0 0 1px rgba(120,96,80,.24), 4px 5px 0 rgba(82,60,72,.15); }
.envelope::after { content: ''; position: absolute; left: 0; right: 0; top: 0; height: 60%; z-index: -1; background: linear-gradient(90deg, #f3e9d6 0 50%, #e9dcc4 50% 100%); clip-path: polygon(0 0, 100% 0, 50% 100%); }
.tab { position: relative; padding: 3px 26px 3px 8px; background: linear-gradient(225deg, transparent 14px, #fbf5e8 14px); filter: drop-shadow(0 0 .6px rgba(110,86,70,.9)) drop-shadow(3px 4px 0 rgba(82,60,72,.15)); }
.tab::after { content: ''; position: absolute; right: 0; top: 0; width: 14px; height: 14px; background: linear-gradient(225deg, transparent 50%, #dccbae 50%); }
.card { position: relative; isolation: isolate; width: 232px; min-height: 300px; background: linear-gradient(180deg, #fffaf1, #f5ecdb); box-shadow: 0 0 0 1px rgba(120,96,80,.24), 6px 8px 0 rgba(82,60,72,.16); transform: rotate(-1.5deg); animation: unfold .6s cubic-bezier(.2,1.25,.4,1) backwards; }
.card::before { content: ''; position: absolute; left: 0; right: 0; top: 0; height: 118px; z-index: -1; background: linear-gradient(90deg, #f29074 0 50%, #e2735a 50% 100%); clip-path: polygon(0 0, 100% 0, 50% 100%); }
@keyframes unfold { from { transform: perspective(700px) rotateX(-88deg); opacity: 0; } to { transform: perspective(700px) rotateX(0) rotate(-1.5deg); opacity: 1; } }
.ribbon { padding: 12px 64px 14px; font: 900 54px/1 'Zen Maru Gothic', sans-serif; color: #fffbf3; background: linear-gradient(180deg, #ee8466 0 50%, #d8644b 50% 100%); clip-path: polygon(0 0, 100% 0, calc(100% - 22px) 50%, 100% 100%, 0 100%, 22px 50%); }
